mapper.select:
select * from (
    select id,conversation_id,reply_to_message_id,sequence_no,role,content,status,
           answer_disclosure_mode,error_code,client_message_id,citations::text as citations,create_time,completed_time
      from cm_ai_message where conversation_id=#{conversationId}
      and sequence_no < #{beforeSequence}
     order by sequence_no desc limit #{limit}
) page order by sequence_no

select * from (
    select id,conversation_id,reply_to_message_id,sequence_no,role,content,status,
           answer_disclosure_mode,error_code,client_message_id,citations::text as citations,create_time,completed_time
      from cm_ai_message where conversation_id=#{conversationId} and status='COMPLETED'
     order by sequence_no desc limit #{limit}
) recent order by sequence_no
